def invoke(worker, **options):
    from ipfs_accelerate_py.agent_supervisor.runtime.multi_supervisor_runner import (
        DATABASE_PROGRAM_ENV_NAMES, STATE_CREDENTIAL_ENV_NAMES,
    )
    # The host fixture keeps its live owner; emulate only the deployed worker's
    # credential scrub around this same-process authored provider invocation.
    with pytest.MonkeyPatch.context() as isolated_worker:
        for name in (*DATABASE_PROGRAM_ENV_NAMES, *STATE_CREDENTIAL_ENV_NAMES,
                     "IPFS_ACCELERATE_AGENT_STATE_OWNER_TOKEN"):
            isolated_worker.delenv(name, raising=False)
        return runner.run(prompt=worker.prompt, provider="codex_cli", model="pinned", timeout=1,
            max_output_tokens=128, semantic_repository=worker.case.root,
            public_instruction_artifact=worker.request["artifact"],
            public_instruction_sha256=worker.request["expected_sha256"],
            public_instruction_task_cid=worker.task.task_cid, **options)

